from pathlib import Path
import json,gzip,csv,hashlib
import numpy as np,pandas as pd
home=Path(__file__).resolve().parent;res=home/'results'
def df(n):return pd.read_csv(res/n)
def md(headers,rows):
    return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in rows)
def job():
    cut=json.loads((res/'thresholds.json').read_text());s=cut['seed'];d=df('block_medians.csv');st=df('native10_stage_medians.csv');op=df('known_threshold_grid.csv');im=df('imperfect_by_stratum.csv');ic=df('imperfect_threshold_grid.csv');v=df('validation_selection.csv');raw=df('deterministic.csv');nn=df('neural_pilot.csv')
    native=['A','B','C','UMa'];o=op[op.family=='equal_profile'];p=op[(op.tau==.15)&op.family.isin(native)]
    fmt=lambda x:f'{float(x):.3f}';ms=lambda x:f'{x/1e6:.1f}'
    validgroups=[]
    for _,r in v.iterrows():validgroups.append([r.label,int(r.n),fmt(r.score),fmt(r.median_G),f'{r.median_ms:.2f}'])
    methods=['sequential','equal_match','cold','subgrad','neural'];pretty=['Sequential / equal','Matching / equal then power search','Cold price repair','Resource subgradient + P3','Locked factor graph']
    totals=[]
    for m,lab in zip(methods,pretty):
        a=st[st.method==m].set_index('k');totals.append([lab]+[f'{a.loc[k,"G"]:.3f} / {ms(a.loc[k,"total_ns"])}' if k in a.index else '—' for k in [16,32,64]])
    stages=[]
    for m in ['subgrad','neural']:
        for _,r in st[(st.method==m)&st.k.isin([32,64])].iterrows():
            stages.append([m,int(r.k)]+[ms(r[f]) for f in ['endpoint_ns','enclosure_ns','matching_ns','primal_ns','proposer_ns','receipt_ns','total_ns']])
    gaprows=[]
    for fam in native+['O1_60','asu_campus1']:
        r=d[(d.family==fam)&(d.k==32)&(d.db==10)&(d.method=='subgrad')]
        gaprows.append([fam,len(r)]+[fmt(y) for y in [r.G.quantile(.05),r.G.median(),r.G.quantile(.95),r.dc.median(),r.Sd.median()]])
    order=['C','UMa'];ir=[]
    for fam in order:
        for arm in ['fixed','scaled']:
            a=im[(im.family==fam)&(im.db==10)&(im.arm==arm)].iloc[0];b=ic[(ic.gap==cut['secondary']['gap'])&(ic.ratio==cut['secondary']['retention'])&(ic.family==fam)&(ic.arm==arm)].iloc[0]
            ir.append([fam,arm,fmt(a.G_P_median),f'{100*a.retention_median:.1f}%',f'{int(a.F_hits)}/{int(a.P_hits)}/{int(a.joint_hits)}',f'{int(b["count"])}/24'])
    witness={}
    for f in ['det_receipts.jsonl.gz','neural_receipts.jsonl.gz']:
        with gzip.open(res/f,'rt') as fp:
            for line in fp:
                r=json.loads(line)['receipt'];key=r['witness'];witness[key]=witness.get(key,0)+1
    train=[json.loads((res/f'seed_{x}.json').read_text()) for x in (1729,2718,3141)]
    text='# Gate 2: solver, pilot benchmark and hardware replay\n\nResearch execution record · 13 November 2026 · pilot data only\n\n'
    text+='**Disposition: NO-GO for the preregistered Gate 3 campaign.** Gate 1 remains externally **PASSED**. Of 96 native 10 dB pilot blocks per size, the locked proposer met the loosest allowed gap and the deadline on **46/96 at K=32** (47.9%; 80% required) and **63/96 at K=64** (65.6%; 60% required). There is no common primary threshold. The best deterministic comparator also beat the neural candidate on validation. These are informative failures; no Gate 3 topology, tile, or label was opened.\n\n'
    text+='## 1. Verifier and soundness\n\nA raw binary channel and optional balls enter the CPU checker. It builds outward gain/correlation bounds for every pair/tone, caches unpriced roots, tightens priced tangents and a bounded number of complete 4×4 subdivisions, integerizes at Γ=2⁴⁰, checks a blossom dual or P3 repair, and verifies the Hungarian bijection. The feasible branch projects powers and tries four gradient steps. The receipt serializes the dyadic receiver and four exact integer numerators over a shared denominator. [Method and proof details](IMPLEMENTATION.md).\n\n'
    text+=f'**Observed consistency violations: 0** over {len(raw):,} deterministic timed decisions and {len(nn):,} locked neural timed decisions. An independent CPU process rebuilt all **4,320 + 192** distinct pilot receipts from raw bytes without model weights. Winning witness types across those 4,512 receipts: {", ".join(f"{k}: {n:,}" for k,n in sorted(witness.items()))}. Missing-witness fallback incidents in the timed rows: {int(raw.fallback.sum()+nn.fallback.sum())}. Deliberately corrupting a nonzero odd-set witness failed as expected; injected export failure exercised P3. The small-case suite also checked Gram coefficients against exact rationals, 1,257 log arguments against 90-digit Decimal, K≤6 exhaustive labelled schedules on a three-level feasible power grid and reconstructed ledgers. No claim of exhaustive global optimum comparison is made for the large continuous cases.\n\n'
    text+='## 2. Deterministic suite before training\n\nThere are 24 independent topologies in each of CDL-A/B/C and native four-site UMa; each is reused across K=16/32/64 and SNR=0/10/20 dB. Each original DeepMIMO scene contributes 12 disjoint buffered tiles under the same matrix. This gives 1,080 scenario/size/SNR cells × four methods × three rotated repeats. Batch size one; normalize at 0.1 W over the full block, preserving relative gains. The table gives the median block gap in bit/s/Hz / median total receipt milliseconds at 10 dB over the four equally sized native families.\n\n'+md(['Policy','K=16','K=32','K=64'],totals)
    text+='\nStage medians (ms) use the per-block median repeat. The primal stage includes its own matching and refinement. Proposal includes CPU/GPU transfers and the local bridge. Independent medians do not add to the median total.\n\n'+md(['Method','K','Input','Boxes','Dual/label','Primal','Proposal','JSON','Total'],stages)
    text+='\nSubgradient dispersion at K=32, 10 dB. Conflict and prior spread are converted from aggregate nats by division by S ln 2, just as for G. Exact counters, all profiles, all SNRs and the three quantiles of all stages are in [the distribution table](results/stratified_distributions.csv); [raw stopwatch records](results/deterministic.csv) are also provided.\n\n'+md(['Family/case','n','G p05','G p50','G p95','Conflict p50','S·d p50'],gaprows)
    text+='\n## 3. Proposer training and frozen comparison\n\nExactly three width-32 residual message-passing layers update pair–tone factors, users, pairs and tones. The heads output primal scores, powers, prices, root/child anchor coordinates and priority. The full root/box heads are included in the GPU target. Each of three seeds saw 4,096 fit blocks once, in 513 Adam steps (batch ≤8, learning rate 0.001). Teachers used only fit topologies and measured split reductions including sibling comparisons. No ray, UMa, Rice or K=64 data entered training. Each seed was evaluated on the same 256 new validation topologies, 64 per fitted family.\n\n'
    text+=md(['Seed or comparator','n','Mean ECDF score','Median G','Median ms'],validgroups)
    hh=cut['model_sha256'];txt=(f'Seed **{s}** won among the neural seeds. Its weight SHA-256 is `{hh}`. **Subgradient + P3** won among the deterministic policies. The learned median gap was **0.10225** against **0.09331** bit/s/Hz; the difference of medians is +0.00894 (larger is worse). This is not evidence of neural tightening over the strongest comparator.');text+='\n'+txt+'\n\n'
    text+=md(['K','Encoder GPU p95 ms','Full GPU p50 / p95 ms','Receipt p50 / p95 ms'],[[k,f"{cut['forward'][str(k)]['encoder_p95']:.2f}",f"{cut['forward'][str(k)]['p50']:.2f} / {cut['forward'][str(k)]['p95']:.2f}",f"{cut['end_to_end'][str(k)]['p50_ms']:.1f} / {cut['end_to_end'][str(k)]['p95_ms']:.1f}"] for k in [32,64]])
    text+='\nThe synchronized GPU p95 exceeds 2 ms at both primary sizes on this Quadro RTX 4000 with Max-Q Design (8 GB). GPU figures above are CUDA events per individual invocation; receipt percentiles are across topology-level medians of three raw-to-JSON wall times. Calibrations, offline teachers and file I/O were outside the receipt clock. Other workload phases could overlap the bench, notably capture transfers during neural timing; no passive clock-lock or exclusive-host guarantee is claimed. The frozen candidate was timed after model selection, so separate-phase comparisons do not control for simultaneous host load.\n\n'
    text+='## 4. Imperfect CSI and Figure 3\n\nThe signed orthogonal Gaussian anchor at N=16, K=32, A²=160 and v²=1/32 has *zero scheduler conflict* and a common oracle upper. Switching the lower endpoint reduces the expected certified gap from 3.153709814 to 1.335321612 bit/s/Hz (difference 1.818388202 in the reported numerical evaluations). Fixed pilot precision leaves a cross-user term 1+ε² in the lower rate, about 1.25 at the representative projected radius. This is an obstruction for this certificate in this model, not a universal limit on actual received throughput.\n\n![Figure 3 pilot panels](results/figure3_pilot.png)\n\n'
    text+='Separate fresh conformal splits had 256 whole 64-user topologies per profile, with the first 32 nested users scheduled; rank 251/256 was used separately for each 2.5% tail. At 10 dB the fixed arm uses Eₚ=32 and the scaled arm Eₚ=320. Utility uses the projected lower endpoint alone for both metrics. The locked secondary pair is **Gₚ ≤0.50 bit/s/Hz and Lₚ/Uꜰ ≥0.95**, with positive Lₚ and one-second delivery. Each row must pass on at least 12/24 pilots. The full [pre-result protocol](PILOT_LOCK.md), scores and full cross-grid accompany the package.\n\n'+md(['Profile','Energy','Gₚ median','Lₚ/Uꜰ median','F / P / joint hits of 24','Utility passes'],ir)
    text+='\nAll 288 imperfect pilot decisions passed the event-conditional lower and upper consistency checks. Conformal coverage misses are events counted in their own right, not soundness violations. Different SNRs and energy arms reuse standardized noise and topology by design; 288 decisions are not 288 independent topologies. Pilot selection does not validate a success rate on future blocks.\n\n'
    text+='## 5. Rice RENEW: inventory and actual replay\n\n'+(home/'RICE_RESULTS.md').read_text(encoding='utf8')+'\n\n'
    text+='## 6. Thresholds, budget and decision\n\nThe known-channel pass counts at the unchanged latency caps, 250 ms and 1,000 ms, are:\n\n'+md(['τ (bit/s/Hz)','K=32 by 250 ms','K=64 by 1,000 ms'],[[t,f"{int(o[(o.k==32)&(o.tau==t)].pass_count.iloc[0])}/96",f"{int(o[(o.k==64)&(o.tau==t)].pass_count.iloc[0])}/96"] for t in [.02,.05,.10,.15]])
    text+='\nThe primary τ is **unset**. The two latency caps remain the original deadlines, not new measured targets. The complete [per-family threshold grid](results/known_threshold_grid.csv) keeps over-deadline receipts in the denominator.\n\n'
    text+=f"Total GPU fitting across seeds was {sum(x['seconds'] for x in train):.1f} s ({sum(x['seconds'] for x in train)/3600:.4f} GPU-hours). The observed deterministic pilot service time was {cut['det_pilot_hours']:.3f} h. Scaling the measured four-baseline matrix to 128 native blocks/family and 64 ray tiles/scene gives {cut['native_deterministic_hours']:.2f} + {cut['ray_deterministic_hours']:.2f} workstation-hours; the neural native K=32/64 part across three SNRs adds about {cut['neural_K32_64_native_hours']:.2f} h, assuming 10 dB throughput at the other SNRs. These are subset projections, not a measured duration for the full campaign. The ≤24 GPU-hour training reserve is ample for the measured models. The ≤120 elapsed workstation-hour / ≤500 GB scratch allowance is **not confirmed** for small-K certified references, ablations, uncertainty, physical-data processing and all publication runs. The host has 8 physical cores/16 logical threads rather than the proposed 20-core workstation; Rice needs streaming or one-at-a-time local staging. Full Gate 3 is not authorized by these results. Re-engineer and preregister a fresh, independent pilot population before revisiting the primary lock.\n\n"
    text+='**Artifact map.** [Replay and dependencies](README.md) · [Raw input hashes, block IDs and bin selections](results/channel_manifest.csv) · [Selection and frozen weights](results/selection.json) · [Known/secondary lock file](results/thresholds.json) · [Exact CPU replay logs](audit_deterministic.log) · [GPU-candidate replay](audit_neural.log). Gate 1 signed source remains unchanged.\n'
    text=text.replace('This is not evidence of neural tightening over the strongest comparator.','On matched validation blocks the learned gap was smaller in 89/256 cases; its median paired change was +0.01866 bit/s/Hz. This is not evidence of neural tightening over the strongest comparator.')
    text=text.replace('The full root/box heads are included in the GPU target.','All evaluated heads are included in the GPU time. Implementation detail: child-head predictions update priority at preselected factors. Root endpoint suggestions are pooled by incident user/tone for the separable tangent, and the 4×4 children use mixed-SINR bounds. This is not an evaluation of distinct tangent placements at each child. The measured latency includes the child-head calls.')
    phase2=pd.read_csv(home/'teachers/manifest.csv')
    text=text.replace('No ray, UMa, Rice or K=64 data entered training.',f"The {len(phase2):,} deterministic teachers used {phase2.teacher_ns.sum()/1e9:.1f} aggregate service seconds (median teacher gap {phase2.G.median():.3f}); {phase2.num_visited.sum():,} root labels and {phase2.strict_priority_comparisons.sum():,} strictly ordered sibling comparisons were retained. No ray, UMa, Rice or K=64 data entered training.")
    text=text.replace('The primary τ is **unset**.','![Known-channel joint pilot ECDF](results/known_pilot_ecdf.png)\n\nAt K=32 all 96 candidate pilot medians arrived by the deadline, but 50 gaps exceeded 0.15. At K=64, 84/96 arrived in time and all 63 blocks meeting the gap did so on time. UMa passed only 1/24 at K=32 and 0/24 at K=64. A faster GPU alone cannot fix the K=32 miss. [Gap versus deadline attribution](results/deadline_gap_attribution.csv). The primary τ is **unset**.')
    text=text.replace('A faster GPU alone cannot fix the K=32 miss.', 'The strongest deterministic comparator reached 73/96 at K=32 and 72/96 at K=64 at 0.15; it too misses 80% at K=32. A faster GPU alone cannot fix the K=32 miss.')
    audit=home/'audit_neural.log'
    assert 'neural_receipts.jsonl.gz 192' in audit.read_text() and 'det_receipts.jsonl.gz 4320' in (home/'audit_deterministic.log').read_text()
    (home/'REPORT.md').write_text(text,encoding='utf8')
if __name__=='__main__':job()

